steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    {
      projects(first: 50) {
        nodes {
          id
          name
          targetDate
          lead {
            id
            name
            email
          }
        }
      }
      users(first: 50) {
        nodes {
          id
          name
          email
        }
      }
    }
  "
  }'
